  $('#editor-kicker').textContent='CANONICAL SCHEMA TYPE';$('#editor-title').textContent=s.title||s.properties?.kind?.const||C.unesc(path.split('/').pop()||labelSchema(doc));$('#editor-path').textContent=doc+'#'+path;
